mapper.delete:
DELETE FROM ${tableName}
WHERE ts > #{startTime}
  AND ts <= #{endTime}

mapper.select:
SELECT ts, slot_no, raw_baseline_e6, actual_window_mean_e6,
       baseline_window_mean_e6, k_e6, final_baseline_e6,
       correction_status, calculation_remark, trace_id,
       calc_version, generated_at, corrected_at, cons_no, data_date
FROM st_user_baseline_load
WHERE cons_no IN

    #{consNo}

  AND ts >= #{startTime}
  AND ts < #{endTime}
ORDER BY cons_no, ts
